"use strict";
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const crypto = require("node:crypto");
const sourceMap = require("./source-maps.cjs");

const root = path.resolve(__dirname, "..");
const check = process.argv.includes("--check");
const layout = JSON.parse(fs.readFileSync(path.join(root, "source-map.json"), "utf8"));
const header = "// Generated by npm run build. Edit the source files listed in source-map.json.\n";
const outputs = new Map();
const used = new Set();
for (const bundle of layout.bundles) {
  if (!/^assets\/(scripts|styles)\/[A-Za-z0-9_.-]+\.(js|css)$/.test(bundle.output) || outputs.has(bundle.output))
    throw Error("Invalid or duplicate build output: " + bundle.output);
  if (!Array.isArray(bundle.sources) || !bundle.sources.length) throw Error("Bundle has no sources: " + bundle.output);
  const fragments = bundle.sources.map(name => {
    if (!name.startsWith("src/") || name.includes("..") || used.has(name)) throw Error("Invalid or duplicate source: " + name);
    used.add(name);
    return fs.readFileSync(path.join(root, name), "utf8").replace(/\r\n/g, "\n").replace(/\n?$/, "\n");
  });
  const content = fragments.map((fragment, index) =>
    (bundle.scope === "css" ? "/* Source: " + bundle.sources[index] + " */\n" : "// Source: " + bundle.sources[index] + "\n") + fragment).join("");
  const wrappers = {
    global: ["", ""],
    workspace: ["(function () {\n", "})();\n"],
    periodic: ["(function (root) {\n", "})(globalThis);\n"],
    course: ['(function (root) {\n"use strict";\nroot.EduCourseUI = function (api) {\n', "};\n})(globalThis);\n"],
    css: ["", ""],
  };
  if (!wrappers[bundle.scope]) throw Error("Unknown source scope: " + bundle.scope);
  const [before, after] = wrappers[bundle.scope];
  const prefix = (bundle.scope === "css" ? "/* Generated by npm run build; edit src/styles. */\n" : header) + before;
  const mapName = path.posix.basename(bundle.output) + ".map";
  const mapLink = bundle.scope === "css" ? "/*# sourceMappingURL=" + mapName + " */\n" : "//# sourceMappingURL=" + mapName + "\n";
  const compiled = prefix + content + after + mapLink;
  if (bundle.scope !== "css") new vm.Script(compiled, { filename: bundle.output });
  outputs.set(bundle.output, compiled);
  outputs.set(bundle.output + ".map", sourceMap(bundle.output, bundle.sources, fragments, prefix));
}
function sourceFiles(directory) {
  return fs.readdirSync(path.join(root, directory), { withFileTypes: true }).flatMap(entry =>
    entry.isDirectory() ? sourceFiles(directory + "/" + entry.name) : /\.(js|css)$/.test(entry.name) ? [directory + "/" + entry.name] : []);
}
for (const name of sourceFiles("src")) {
  if (!used.has(name)) throw Error("Unmapped source file: " + name);
}

// Cache version is a fingerprint of the entire deployable shell, not just HTML.
const { applicationFiles } = require("./application-files.cjs");
const catalog = applicationFiles(root, { generated: new Set(outputs.keys()), contents: outputs });
const cached = [...catalog.keys()].filter(name => name !== "service-worker.js");
// Normalize text before hashing so Git's LF checkout policy does not change a
// release. Hash worker logic with its generated fields replaced to avoid a cycle.
let worker = fs.readFileSync(path.join(root, "service-worker.js"), "utf8").replace(/\r\n/g, "\n");
if (!/const VERSION = "[^"]+";/.test(worker) || !/const FILES\s*=\s*\[[\s\S]*?\];/.test(worker))
  throw Error("Service worker is missing generated VERSION or FILES fields");
const fileDeclaration = "const FILES = " + JSON.stringify(cached, null, 2) + ";";
const workerTemplate = worker.replace(/const VERSION = "[^"]+";/, 'const VERSION = "__BUILD_VERSION__";')
  .replace(/const FILES\s*=\s*\[[\s\S]*?\];/, fileDeclaration);
const hash = crypto.createHash("sha256");
for (const name of [...cached].sort()) {
  hash.update(name + "\0");
  hash.update(outputs.has(name) ? outputs.get(name) : fs.readFileSync(path.join(root, name), "utf8").replace(/\r\n/g, "\n"));
}
hash.update("service-worker.js\0").update(workerTemplate);
worker = workerTemplate.replace('"__BUILD_VERSION__"', '"' + hash.digest("hex").slice(0, 16) + '"');
new vm.Script(worker, { filename: "service-worker.js" });
outputs.set("service-worker.js", worker);
const stale = [];
for (const [name, content] of outputs) {
  const target = path.join(root, name);
  const actual = fs.existsSync(target) ? fs.readFileSync(target, "utf8").replace(/\r\n/g, "\n") : null;
  if (actual === content) continue;
  if (check) stale.push(name);
  else { fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, content, "utf8"); }
}
if (stale.length) throw Error("Generated files are stale. Run npm run build: " + stale.join(", "));
console.log(`${check ? "Verified" : "Built"} ${layout.bundles.length} bundles from ${used.size} source files.`);
